// Turns an axios error into a message that actually tells you what happened,
// instead of a generic "failed" that looks identical whether the server
// rejected your input or was never reachable in the first place.
export function getErrorMessage(err, fallback) {
  if (err.response) {
    // Server responded with an error status — use its message if present.
    return err.response.data?.message || fallback;
  }
  if (err.request) {
    // Request went out but no response came back: server down, wrong URL,
    // or blocked by CORS.
    return "Can't reach the server. Make sure the backend is running and VITE_API_URL is correct.";
  }
  return err.message || fallback;
}
